ALTER TABLE "round_commands" DROP CONSTRAINT "round_commands_type_check", ADD CONSTRAINT "round_commands_type_check" CHECK ("type" in ('start', 'strike_resolution', 'start_prep', 'cancel_prep', 'start_speech', 'yield', 'interrupt', 'offer_poi', 'withdraw_poi', 'accept_poi', 'decline_poi', 'end_poi', 'forfeit', 'leave', 'complete', 'submit_ballot', 'change_judge', 'stop', 'void_source', 'check_in', 'adjudicate'));--> statement-breakpoint
-- INTX-16 backfill: points of information replace interruptions. A format that
-- offered any interruption choice offers points of information within Daisy's
-- bounds; a setting that took the floor or opened every microphone takes points
-- of information at the parliamentary defaults; one that declined them declines.
-- Every stored definition, preset, Room, Round and league floor setting is
-- rewritten, since their schemas are strict (ADR 0023). This never refuses: a
-- Round live across the release keeps its prep, and any interruption floor it
-- held returns to the speaker.
UPDATE "format_revisions" SET "definition" = jsonb_set("definition" #- '{configurable,interaction,interruptions}', '{configurable,interaction,pointsOfInformation}', CASE WHEN jsonb_typeof("definition" #> '{configurable,interaction,interruptions}') = 'object' THEN '{"protectedStartMs":{"min":0,"max":120000},"protectedEndMs":{"min":0,"max":120000},"maxDurationMs":{"min":5000,"max":30000},"offerLapseMs":{"min":5000,"max":30000}}'::jsonb ELSE 'null'::jsonb END) WHERE "definition" #> '{configurable,interaction}' ? 'interruptions';--> statement-breakpoint
UPDATE "format_presets" SET "config" = ("config" - 'interruptions') || jsonb_build_object('pointsOfInformation', CASE WHEN jsonb_typeof("config" -> 'interruptions') <> 'object' THEN 'null'::jsonb WHEN "config" #>> '{interruptions,mode}' IN ('enabled', 'open') THEN '{"enabled":true,"protectedStartMs":60000,"protectedEndMs":60000,"maxDurationMs":15000,"offerLapseMs":10000}'::jsonb ELSE '{"enabled":false}'::jsonb END) WHERE "config" ? 'interruptions';--> statement-breakpoint
UPDATE "rooms" SET "config" = ("config" - 'interruptions') || jsonb_build_object('pointsOfInformation', CASE WHEN jsonb_typeof("config" -> 'interruptions') <> 'object' THEN 'null'::jsonb WHEN "config" #>> '{interruptions,mode}' IN ('enabled', 'open') THEN '{"enabled":true,"protectedStartMs":60000,"protectedEndMs":60000,"maxDurationMs":15000,"offerLapseMs":10000}'::jsonb ELSE '{"enabled":false}'::jsonb END) WHERE "config" ? 'interruptions';--> statement-breakpoint
UPDATE "rooms" SET "rules_snapshot" = jsonb_set("rules_snapshot" #- '{interaction,interruptions}', '{interaction,pointsOfInformation}', CASE WHEN "rules_snapshot" #>> '{interaction,interruptions,allowed}' IN ('enabled', 'open') THEN '{"allowed":true,"protectedStartMs":60000,"protectedEndMs":60000,"maxDurationMs":15000,"offerLapseMs":10000}'::jsonb ELSE '{"allowed":false}'::jsonb END) WHERE "rules_snapshot" #> '{interaction}' ? 'interruptions';--> statement-breakpoint
UPDATE "rounds" SET "room_config_snapshot" = ("room_config_snapshot" - 'interruptions') || jsonb_build_object('pointsOfInformation', CASE WHEN jsonb_typeof("room_config_snapshot" -> 'interruptions') <> 'object' THEN 'null'::jsonb WHEN "room_config_snapshot" #>> '{interruptions,mode}' IN ('enabled', 'open') THEN '{"enabled":true,"protectedStartMs":60000,"protectedEndMs":60000,"maxDurationMs":15000,"offerLapseMs":10000}'::jsonb ELSE '{"enabled":false}'::jsonb END) WHERE "room_config_snapshot" ? 'interruptions';--> statement-breakpoint
UPDATE "rounds" SET "rules_snapshot" = jsonb_set("rules_snapshot" #- '{interaction,interruptions}', '{interaction,pointsOfInformation}', CASE WHEN "rules_snapshot" #>> '{interaction,interruptions,allowed}' IN ('enabled', 'open') THEN '{"allowed":true,"protectedStartMs":60000,"protectedEndMs":60000,"maxDurationMs":15000,"offerLapseMs":10000}'::jsonb ELSE '{"allowed":false}'::jsonb END) WHERE "rules_snapshot" #> '{interaction}' ? 'interruptions';--> statement-breakpoint
UPDATE "settings" SET "value" = ("value" - 'interruptions') || jsonb_build_object('pointsOfInformation', CASE WHEN jsonb_typeof("value" -> 'interruptions') <> 'object' THEN 'null'::jsonb WHEN "value" #>> '{interruptions,mode}' IN ('enabled', 'open') THEN '{"enabled":true,"protectedStartMs":60000,"protectedEndMs":60000,"maxDurationMs":15000,"offerLapseMs":10000}'::jsonb ELSE '{"enabled":false}'::jsonb END) WHERE "key" = 'room.floor' AND "value" ? 'interruptions';--> statement-breakpoint
-- INTX-1: the checkpoint's prep is one state, and its point of information starts empty.
UPDATE "rounds" SET "runtime_state" = ("runtime_state" - 'active_prep' - 'prep_ended_at' - 'floor') || jsonb_build_object('version', 2, 'prep', CASE WHEN jsonb_typeof("runtime_state" -> 'active_prep') = 'object' THEN jsonb_build_object('phase', 'running', 'side', "runtime_state" #> '{active_prep,side}', 'started_at', "runtime_state" #> '{active_prep,started_at}') WHEN jsonb_typeof("runtime_state" -> 'prep_ended_at') = 'string' THEN jsonb_build_object('phase', 'lead', 'ended_at', "runtime_state" -> 'prep_ended_at') ELSE '{"phase":"idle"}'::jsonb END, 'point_of_information', '{"phase":"none"}'::jsonb) WHERE "runtime_state" ->> 'version' = '1';
